# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PAST PERFECT TENSE (HAD + V3) VE ZAMAN ÇİZELGESİ (TIMELINE)</text>\n  <rect x="25" y="48" width="650" height="82" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <line x1="60" y1="92" x2="640" y2="92" stroke="#1e40af" stroke-width="3"/>\n  <polygon points="638,86 652,92 638,98" fill="#1e40af"/>\n  <circle cx="170" cy="92" r="9" fill="#dc2626"/>\n  <text x="170" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">1st Action (Daha Önce)</text>\n  <text x="170" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">PAST PERFECT (had + V3)</text>\n  <circle cx="390" cy="92" r="9" fill="#16a34a"/>\n  <text x="390" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">2nd Action (Daha Sonra)</text>\n  <text x="390" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">SIMPLE PAST (V2)</text>\n  <circle cx="590" cy="92" r="8" fill="#0284c7"/>\n  <text x="590" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0369a1">NOW (Şimdi)</text>\n  <text x="590" y="114" text-anchor="middle" font-size="10.5" fill="#0c4a6e">Present</text>\n\n  <rect x="25" y="142" width="310" height="90" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="180" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Grammatical Forms (Yapı)</text>\n  <text x="40" y="184" font-size="10.5" fill="#334155">• (+) Subject + <tspan font-weight="bold" fill="#b45309">had + V3</tspan> (had gone / had eaten)</text>\n  <text x="40" y="202" font-size="10.5" fill="#334155">• (-) Subject + <tspan font-weight="bold" fill="#b45309">hadn\'t + V3</tspan> (hadn\'t seen)</text>\n  <text x="40" y="220" font-size="10.5" fill="#334155">• (?) <tspan font-weight="bold" fill="#b45309">Had</tspan> + Subject + <tspan font-weight="bold" fill="#b45309">V3</tspan> ...?</text>\n\n  <rect x="365" y="142" width="310" height="90" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="520" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Cause &amp; Effect in the Past</text>\n  <text x="380" y="186" font-size="10.5" fill="#334155">• He <tspan font-weight="bold" fill="#166534">failed</tspan> the exam (2nd - Result / V2)</text>\n  <text x="380" y="204" font-size="10.5" fill="#334155">  because he <tspan font-weight="bold" fill="#b91c1c">hadn\'t studied</tspan> enough.</text>\n  <text x="380" y="220" font-size="10" fill="#475569">  (1st Action - Earlier Cause / had + V3)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ZAMAN BAĞLAÇLARI (TIME CLAUSES) FORMÜL TABLOSU</text>\n  <rect x="20" y="45" width="320" height="198" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">1. AFTER / AS SOON AS Grubu</text>\n  <rect x="32" y="80" width="296" height="44" rx="6" fill="#ffffff" stroke="#38bdf8" stroke-width="1.5"/>\n  <text x="180" y="99" text-anchor="middle" font-size="11" font-weight="bold" fill="#0284c7">After / As soon as + Past Perfect (had V3),</text>\n  <text x="180" y="115" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Simple Past (V2)</text>\n  <text x="34" y="144" font-size="10.5" fill="#334155">• <tspan font-weight="bold">After</tspan> she <tspan font-weight="bold" fill="#b91c1c">had graduated</tspan> from university,</text>\n  <text x="42" y="159" font-size="10.5" fill="#334155">she <tspan font-weight="bold" fill="#15803d">found</tspan> a job in a hospital.</text>\n  <text x="34" y="184" font-size="10.5" fill="#334155">• <tspan font-weight="bold">As soon as</tspan> the storm <tspan font-weight="bold" fill="#b91c1c">had stopped</tspan>,</text>\n  <text x="42" y="199" font-size="10.5" fill="#334155">the villagers <tspan font-weight="bold" fill="#15803d">repaired</tspan> their roofs.</text>\n  <text x="34" y="224" font-size="10" font-weight="bold" fill="#0369a1">Because + Past Perfect (Neden) → Simple Past (Sonuç)</text>\n\n  <rect x="360" y="45" width="320" height="198" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">2. BEFORE / BY THE TIME / WHEN Grubu</text>\n  <rect x="372" y="80" width="296" height="44" rx="6" fill="#ffffff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="99" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">Before / By the time / When + Simple Past (V2),</text>\n  <text x="520" y="115" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Past Perfect (had V3)</text>\n  <text x="374" y="144" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Before</tspan> the ambulance <tspan font-weight="bold" fill="#15803d">arrived</tspan>,</text>\n  <text x="382" y="159" font-size="10.5" fill="#334155">first-aid teams <tspan font-weight="bold" fill="#b91c1c">had helped</tspan> the injured.</text>\n  <text x="374" y="184" font-size="10.5" fill="#334155">• <tspan font-weight="bold">By the time</tspan> we <tspan font-weight="bold" fill="#15803d">reached</tspan> the airport,</text>\n  <text x="382" y="199" font-size="10.5" fill="#334155">the plane <tspan font-weight="bold" fill="#b91c1c">had already taken off</tspan>.</text>\n  <text x="374" y="224" font-size="10" font-weight="bold" fill="#5b21b6">Until: They waited until the rain had stopped.</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">THEME 3: HARD TIMES VOCABULARY &amp; NARRATIVE SEQUENCERS</text>\n  <rect x="25" y="48" width="310" height="182" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. Hardships &amp; Overcoming Phrases</text>\n  <text x="40" y="96" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">suffer from poverty:</tspan> yoksulluk çekmek</text>\n  <text x="40" y="116" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">make ends meet:</tspan> iki yakayı bir araya getirmek</text>\n  <text x="40" y="136" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">go bankrupt / lose a job:</tspan> iflas etmek / iş kaybetmek</text>\n  <text x="40" y="156" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">overcome obstacles:</tspan> engellerin üstesinden gelmek</text>\n  <text x="40" y="176" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">cope with / deal with:</tspan> zorluklarla başa çıkmak</text>\n  <text x="40" y="196" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">persevere &amp; succeed:</tspan> azmetmek ve başarmak</text>\n\n  <rect x="365" y="48" width="310" height="182" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Narrative Connectors (Öykü Bağlaçları)</text>\n  <text x="380" y="98" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Beginning:</tspan> At first, Initially, To begin with</text>\n  <text x="380" y="122" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Continuing:</tspan> Then, Afterwards, Later on</text>\n  <text x="380" y="146" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Simultaneous:</tspan> Meanwhile, While, As</text>\n  <text x="380" y="170" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Unexpected:</tspan> Suddenly, All of a sudden</text>\n  <text x="380" y="194" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Ending:</tspan> Eventually, Finally, In the end</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
